def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    quadratic = 0.0
    linear = 0.0
    compliance = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        p = props.get(el) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is None or affinity is None or ionization <= 0:
            continue
        hardness = ionization - affinity
        if hardness <= 0:
            continue
        chi = 0.5 * (ionization + affinity)
        quadratic += x * chi * chi / hardness
        linear += x * chi / hardness
        compliance += x / hardness
        amount += x
    if compliance <= 0 or amount <= 0:
        return 0.0
    return float(max(0.0, 0.5 * (quadratic - linear * linear / compliance) / amount))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    coordination = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        contact = min(1.0, max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2 / 0.1225)
        coordination[i] += occ[j] * contact
    total = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or group < 14 or group > 17 or en is None or en < 2.5:
            continue
        expected = 18.0 - group
        total += occ[i] * max(0.0, expected - coordination[i]) / expected
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    adjacency = [[] for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if occ[i] <= 0 or occ[j] <= 0 or radii[i] <= 0 or radii[j] <= 0:
            continue
        if d > 1.25 * (radii[i] + radii[j]):
            continue
        image = edge.get('image')
        if image is None or len(image) != 3:
            continue
        adjacency[i] += [(j, image[0], image[1], image[2])]
    offsets = [None for a in sites]
    finite_amount = 0.0
    amount = 0.0
    for root in range(n):
        if occ[root] <= 0 or radii[root] <= 0 or offsets[root] is not None:
            continue
        offsets[root] = (0, 0, 0)
        queue = [root]
        cursor = 0
        winding = False
        component_amount = 0.0
        while cursor < len(queue):
            i = queue[cursor]
            cursor += 1
            component_amount += occ[i]
            for entry in adjacency[i]:
                j = entry[0]
                expected = (offsets[i][0] + entry[1], offsets[i][1] + entry[2], offsets[i][2] + entry[3])
                if offsets[j] is None:
                    offsets[j] = expected
                    queue += [j]
                elif offsets[j] != expected:
                    winding = True
        amount += component_amount
        if not winding:
            finite_amount += component_amount
    return float(finite_amount / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    subshell = [(props.get(a.get('element')) or {}).get('pymatgen_valence_subshell') for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    selected = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        a = subshell[i]
        b = subshell[j]
        if a is None or b is None or len(a) != 2 or len(b) != 2:
            continue
        if a[0] is None or b[0] is None:
            continue
        w = occ[i] * occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        weight += w
        if (a[0] == 1 and b[0] >= 2) or (b[0] == 1 and a[0] >= 2):
            selected += w
    return float(selected / weight) if weight > 0 else 0.0

